// Verify Razorpay signature and extract payment data
const body = $input.first().json.body || $input.first().json;
const event = body.event;

// Only process payment captured events
if (event !== 'payment.captured' && event !== 'order.paid') {
  return [{ json: { skip: true, event } }];
}

const payment = body.payload?.payment?.entity || body.payload?.order?.entity || {};
const notes = payment.notes || {};

return [{ json: {
  payment_id: payment.id,
  order_id: payment.order_id,
  amount: payment.amount / 100,
  currency: payment.currency || 'INR',
  lead_id: notes.lead_id || null,
  client_id: notes.client_id || 1,
  customer_name: notes.name || payment.email || 'Customer',
  customer_phone: notes.phone || payment.contact?.replace('+91', '') || null,
  description: notes.description || 'Payment received',
  brand: notes.brand || 'BM Academy',
  skip: false
}}];

const payment = $('Parse Payment Data').first().json;
const creds = $('Get WhatsApp Credentials').first().json;

// Build welcome message based on brand
const brandMessages = {
  'BM Academy': `🎉 Welcome to BM Academy, ${payment.customer_name}!

Payment confirmed: Rs ${payment.amount.toLocaleString('en-IN')}
Payment ID: ${payment.payment_id}

Your next steps:
📱 You will be added to the WhatsApp batch group shortly
📅 Course schedule will be shared by tonight
📞 Your counsellor will call within 24 hours

Welcome to the ABM Groups family! 🎓`,
  'BM TechX': `✅ Payment Confirmed — ${payment.customer_name}!

Amount: Rs ${payment.amount.toLocaleString('en-IN')}
Payment ID: ${payment.payment_id}

Your account is now active.

Next steps:
📊 Onboarding call scheduled within 48 hours
📋 Strategy document will be shared
📱 Add Satish on WhatsApp: +91 94038 92971

Thank you for choosing BM TechX! 🚀`,
  'EduConsultants': `🎓 Payment Confirmed — ${payment.customer_name}!

Amount: Rs ${payment.amount.toLocaleString('en-IN')}

Next steps:
📄 Send remaining documents WhatsApp
📞 Detailed counselling call within 24 hours
🌍 University shortlist within 3 working days

Thank you for choosing EduConsultants!`
};

const msg = brandMessages[payment.brand] || `✅ Payment of Rs ${payment.amount} received! Thank you. Our team will contact you within 24 hours. ABM Groups.`;

return [{ json: {
  phone_number_id: creds.phone_number_id,
  wa_access_token: creds.wa_access_token,
  to_phone: '91' + payment.customer_phone,
  message: msg,
  payment
}}];
